{"files":[{"path":"engine.py","text":"from rules import amount, winner_key


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}

    # Apply the cutoff before resolving revisions so an out-of-range revision
    # cannot supersede an eligible event.
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", f"anonymous:{position}")
        key = winner_key(event, position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = f"{account}|{currency}"
        value = amount(event, data["rounding"])
        if event.get("kind") == "refund":
            value = -value
        balances[key] = balances.get(key, 0) + value

    return {"balances": balances}
